const q = String($('When Called').first().json.query || '').toLowerCase().trim();
// The user's own addresses — never suggest these as someone to invite.
const SELF = ['you@example.com','you-alias@example.com','you-alt@example.com','you-personal@example.com'];
const tally = {};
function ensure(email){
  const e = String(email || '').toLowerCase();
  if(!e.includes('@') || SELF.includes(e)) return null;
  if(!tally[e]) tally[e] = { name:'', email:e, messages:0, saved:false };
  return tally[e];
}
// 1) Recent Gmail correspondents (from/to/cc), counted by frequency.
for(const it of $('Search Gmail').all()){
  const j = it.json || {};
  for(const grp of ['from','to','cc']){
    const v = (j[grp] && j[grp].value) || [];
    for(const p of v){
      if(!p || !p.address) continue;
      const t = ensure(p.address); if(!t) continue;
      t.messages++;
      const nm = String(p.name || '').trim();
      if(nm && !t.name) t.name = nm;
    }
  }
}
// 2) Saved Google Contacts (People API connections) — deliberate address book.
const conns = ($('List Contacts').first().json.connections) || [];
for(const person of conns){
  const pname = ((person.names || [])[0] || {}).displayName || '';
  for(const ea of (person.emailAddresses || [])){
    const t = ensure(ea.value); if(!t) continue;
    t.saved = true;
    if(pname && !t.name) t.name = pname;
  }
}
// --- fuzzy name matching (Levenshtein) so 'james' matches 'jaymes' etc. ---
function lev(a,b){
  const m=a.length, n=b.length; if(!m) return n; if(!n) return m;
  let prev=[]; for(let j=0;j<=n;j++) prev[j]=j;
  for(let i=1;i<=m;i++){ const cur=[i];
    for(let j=1;j<=n;j++){ cur[j]=Math.min(prev[j]+1, cur[j-1]+1, prev[j-1]+(a[i-1]===b[j-1]?0:1)); }
    prev=cur; }
  return prev[n];
}
function tokSim(a,b){
  if(a===b) return 1;
  if(a.length>=3 && b.length>=3 && (a.includes(b)||b.includes(a))) return 0.85;
  const L=Math.max(a.length,b.length); if(!L) return 0;
  const s=1 - lev(a,b)/L; return s>=0.7 ? s : 0;
}
function relevance(name, email){
  const qt = q.split(' ').filter(Boolean); if(!qt.length) return 1;
  const local = String(email||'').split('@')[0].split('.').join(' ').split('_').join(' ').split('-').join(' ');
  const nt = (String(name||'').toLowerCase()+' '+local.toLowerCase()).split(' ').filter(Boolean);
  let total=0, hits=0;
  for(const t of qt){ let best=0; for(const w of nt) best=Math.max(best, tokSim(t,w)); total+=best; if(best>=0.7) hits++; }
  if(!hits) return 0;
  return (total/qt.length) + (hits===qt.length ? 0.25 : 0);
}
let list = Object.values(tally).map(p => ({ name:p.name, email:p.email, messages:p.messages, saved:p.saved, rel: relevance(p.name, p.email) }));
// Keep only plausible matches (>=1 close token); when q is blank, keep everything.
if(q) list = list.filter(p => p.rel > 0);
// Rank: name closeness first, then saved-contact tier, then email frequency.
list.sort((a,b) => (b.rel - a.rel) || ((b.saved?1:0)-(a.saved?1:0)) || (b.messages - a.messages));
const top = list.slice(0,8).map(p => ({ json: { name: p.name || null, email: p.email, messages: p.messages, savedContact: p.saved, match: Math.round(p.rel*100)/100 } }));
return top.length ? top : [{ json: { note: 'No contact found close to that name in saved contacts or recent email.', query: q } }];
